]

# Find rectangles by color
def find_rectangles(grid):
    rectangles = {}
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color > 0 and color not in rectangles:
                rect = {'color': color, 'top': r, 'left': c, 'bottom': r, 'right': c, 'empty_interior': 0}
                for dr in range(r, rows):
                    for dc in range(c, cols):
                        if grid[dr][dc] != 0:
                            continue
                        # Check if this cell should be interior (inside the rectangle)
                        if r <= dr <= rect['bottom'] and c <= dc <= rect['right']:
                            rect['empty_interior'] += 1

    return {'rectangles': rectangles}

print("Grid shape:", len(grid), "x", len(grid[0]))
print("\nThe puzzle has hollow rectangular frames made of different colors.")
print("Colors: 1 (4x4 hollow rect), 5 (4x4 hollow rect), 8 (5x5 hollow rect), 9 (5x5 hollow rect)")

# Try: Fill the hollow rectangles (turn them into solid rectangles)
