# Color 1: 4x4 hollow rect at rows 0-3, cols 8-11
# Top: row 0, cols 8-11: 1 1 1 1
# Sides: rows 1-2, cols 8 and 11: 1
# Bottom: row 3, cols 8-11: 1 1 1 1
# Fill interior: rows 1-2, cols 9-10 with 1
for r in range(4):
    for c in range(8, 12):
        if r == 0 or r == 3 or c == 8 or c == 11:
            # Already has border
            pass
        elif 1 <= r <= 2 and 9 <= c <= 10:
            output_grid[r][c] = 1  # Fill interior

# Color 5: 4x4 hollow rect at rows 5-8, cols 0-3
# Fill interior: rows 6-7, cols 1-2 with 5
for r in range(6, 8):
    for c in range(1, 3):
        output_grid[r][c] = 5

# Color 8: 5x5 hollow rect at rows 5-9, cols 5-9
# Fill interior: rows 6-8, cols 6-8 with 8
for r in range(6, 9):
    for c in range(6, 9):
        output_grid[r][c] = 8

# Color 9: 5x5 hollow rect at rows 5-9, cols 14-18
# Fill interior: rows 6-8, cols 15-17 with 9
for r in range(6, 9):
    for c in range(15, 19):
        output_grid[r][c] = 9

# Convert to string format
def grid_to_str(g):
    return "\n".join("[[" + ",".join(str(x) for x in row) + "]," for row in g)[:-1] + "]"

print("Output grid prediction:")
print(grid_to_str(output_grid))

